if (get TextBox_Email.Text = "admin@megaminds.com") and (get PasswordTextBox1.Text = "12345")
then call open another screen (screenName = "HomeScreen")
else set Label_Error.Text to "The data is incorrect!"

// Save data
call TinyDB1.StoreValue(tag = "username", valueToStore = TextBox_Name.Text)
// Retrieve data
set Label_Welcome.Text to call TinyDB1.GetValue (tag = "username", valueIfTagNotThere = "New User")

set global pcChoice to call pick a random item (list = create empty list ["stone", "paper", "scissors"])
if (get global userChoice = get global pcChoice)
then set Label_Status.Text to "Tie!"
else if (get global userChoice = "stone" and get global pcChoice = "scissors")
then set Label_Status.Text to "You are the winner! 🎉"

// Move to the clinic screen with the patient's name sent
call open another screen with start value (screenName = "ClinicScreen", startValue = get studentInfo.name)
// Receive the name on the clinic screen
set Label_PatientName.Text to get start value
